'use client';
import {useCallback,useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {downloadReport,reportUsd} from '@/lib/report-export';
import {DepositHistory,DepositTotalsView} from '@/components/deposit-panel';
import {addDepositDays,depositActivityCsv,depositPeriod,depositRegisterCsv,depositStatusLabel,validateDepositActivity,validateDepositRegister,type DepositActivity,type DepositRegister} from '@/lib/deposits';

type Props={actor:string;tenant:string;property:string;propertyName:string;businessDate:string;disabled?:boolean;onOpen:(reservation:string)=>void};
export function DepositReports(props:Props){const [kind,setKind]=useState<'register'|'activity'>('register');return <><label className="field pilot-report-kind">Security-deposit view<select value={kind} disabled={props.disabled} onChange={e=>setKind(e.target.value as 'register'|'activity')}><option value="register">Current recorded security funds</option><option value="activity">Recorded deposit activity</option></select></label><DepositReport key={props.actor+'/'+props.tenant+'/'+props.property+'/'+kind} {...props} kind={kind}/></>}
function DepositReport({tenant,property,propertyName,businessDate,disabled=false,onOpen,kind}:Props&{kind:'register'|'activity'}){
 const [initialStart]=useState(addDepositDays(businessDate,-6)),[initialEnd]=useState(addDepositDays(businessDate,1)),[start,setStart]=useState(initialStart),[end,setEnd]=useState(initialEnd),[data,setData]=useState<DepositRegister|DepositActivity|null>(null),[loaded,setLoaded]=useState(''),[loading,setLoading]=useState(true),[error,setError]=useState('');
 const alive=useRef(true),sequence=useRef(0),locked=useRef(false);
 const key=tenant+'/'+property+'/'+kind+(kind==='activity'?'/'+start+'/'+end:'');
 const read=useCallback(async(from:string,until:string)=>{if(kind==='activity'&&!depositPeriod(from,until))throw Error('Choose 1–366 recording dates with an exclusive end after the start.');const value=await hotelRpc<unknown>(kind==='register'?'security_deposit_register':'security_deposit_activity',{p_tenant:tenant,p_property:property,...(kind==='activity'?{p_start:from,p_end:until}:{})});if(kind==='register')validateDepositRegister(value,tenant,property);else validateDepositActivity(value,tenant,property,from,until);return value as DepositRegister|DepositActivity},[kind,tenant,property]);
 useEffect(()=>{alive.current=true;const version=++sequence.current;void read(initialStart,initialEnd).then(value=>{if(alive.current&&sequence.current===version){setData(value);setLoaded(tenant+'/'+property+'/'+kind+(kind==='activity'?'/'+initialStart+'/'+initialEnd:''));setError('');setLoading(false)}}).catch(e=>{if(alive.current&&sequence.current===version){setError(e instanceof Error?e.message:'Unable to load deposit reports.');setLoading(false)}});return()=>{alive.current=false}},[read,tenant,property,kind,initialStart,initialEnd]);
 async function refresh(){if(disabled||locked.current)return;locked.current=true;const version=++sequence.current;setLoading(true);setLoaded('');setError('');try{const value=await read(start,end);if(alive.current&&version===sequence.current){setData(value);setLoaded(key)}}catch(e){if(alive.current&&version===sequence.current)setError(e instanceof Error?e.message:'Unable to load deposit reports.')}finally{locked.current=false;if(alive.current&&version===sequence.current)setLoading(false)}}
 const fresh=!!data&&loaded===key&&!loading&&!error&&!disabled,register=fresh&&kind==='register'?data as DepositRegister:null,activity=fresh&&kind==='activity'?data as DepositActivity:null;
 function exportCsv(){if(!fresh||!data)return;try{downloadReport(propertyName+'-security-deposit-'+kind+(kind==='activity'?'-'+start+'-'+end:''),kind==='register'?depositRegisterCsv(data as DepositRegister,propertyName):depositActivityCsv(data as DepositActivity,propertyName))}catch(e){setError(e instanceof Error?e.message:'Unable to export this snapshot.')}}
 return <section className="card pilot-reports"><div className="pilot-report-controls"><div className="section-top"><div><h2>{kind==='register'?'Current recorded security funds':'Recorded security-deposit activity'}</h2><p>Refundable security funds recorded from external evidence, separately from guest folios and revenue.</p></div><button className="secondary" disabled={!fresh} onClick={exportCsv}>Export security-deposit report CSV</button></div><form className="pilot-report-filters" onSubmit={e=>{e.preventDefault();void refresh()}}>{kind==='activity'&&<><label className="field">Deposit recording date from<input type="date" required value={start} disabled={loading||disabled} onChange={e=>setStart(e.target.value)}/></label><label className="field">Deposit recording date until (exclusive)<input type="date" required value={end} disabled={loading||disabled} onChange={e=>setEnd(e.target.value)}/></label></>}<button className="primary" disabled={loading||disabled}>{loading?'Loading…':'Refresh deposit report'}</button></form>{error&&<div className="pilot-error" role="alert">{error}</div>}</div>
 {!fresh?<output className="pilot-empty">{loading?'Loading the selected security-deposit snapshot…':'Load the selected scope before viewing or exporting.'}</output>:data&&<><div className="pilot-report-heading"><span className="pilot-eyebrow">{propertyName}</span><p>Snapshot {data.generated_at} · Current property zone {data.property_time_zone}</p></div><p className="pilot-report-basis">These records do not prove processor settlement, an approved refund, or money applied to a bill. Earlier folio payments are not inferred to be security deposits.</p>{register&&<><DepositTotalsView totals={register.totals}/><p>{register.summary.book_count} explicit books · {register.summary.with_held_count} with funds remaining · {register.summary.zero_held_count} recorded zero balances.</p><p>{register.summary.ended_with_held_count} ended stays have {reportUsd(register.summary.ended_held_minor)} recorded funds remaining and need financial review. Cancelled no-shows are counted once. This is not an approved-refund list.</p><div className="pilot-table-wrap"><table className="pilot-table"><caption>All recorded books, including future, ended, and zero-balance stays</caption><thead><tr><th scope="col">Current guest / reference</th><th scope="col">Current stay</th><th scope="col">Received</th><th scope="col">Returned</th><th scope="col">Reduced</th><th scope="col">Remaining</th><th scope="col">Review</th></tr></thead><tbody>{register.rows.map(row=><tr key={row.book.id}><td>{row.reservation.guest_name??'Guest name unavailable'}<small>{row.reservation.source_booking_id}</small></td><td>{depositStatusLabel(row.reservation)}<small>{row.reservation.arrival??'Unknown'} to {row.reservation.departure??'Unknown'}</small></td><td>{reportUsd(row.book.totals.received_minor)}</td><td>{reportUsd(row.book.totals.refunded_minor)}</td><td>{reportUsd(row.book.totals.reduced_minor)}</td><td>{reportUsd(row.book.totals.held_minor)}</td><td>{row.financial_review_required&&<small>Ended stay — review funds</small>}<button className="text-button" disabled={disabled} onClick={()=>onOpen(row.reservation.id)}>Open deposit record</button></td></tr>)}</tbody></table></div>{!register.rows.length&&<p>No security-deposit books are recorded. Reservations without a book are excluded; this is not a statement that no deposits exist externally.</p>}<p className="muted">Create a first deposit record from the reservation’s Manage screen. New receipts do not change the guest folio.</p></>}{activity&&<><p>{activity.period.start} through {activity.period.end}, exclusive end. Each row uses its book’s stored recording date and frozen zone; there is no single UTC interval.</p><div className="detail-grid"><div>Received in period<b>{reportUsd(activity.totals.received_minor)}</b></div><div>Returned in period<b>{reportUsd(activity.totals.refunded_minor)}</b></div><div>Reduced in period<b>{reportUsd(activity.totals.reduced_minor)}</b></div><div>Net held-record effect<b>{reportUsd(activity.totals.held_effect_minor)}</b></div></div><p>{activity.totals.event_count} recorded events. Period activity is not the current security-funds balance; an empty period does not rule out funds held outside these dates.</p><DepositHistory events={activity.rows.map(row=>row.event)} reservations={Object.fromEntries(activity.rows.map(row=>[row.reservation.id,row.reservation]))} onOpen={onOpen}/></>}<p className="muted">Refresh after changing a deposit record. Export contains the complete loaded records, scope, dates, references, and amount basis.</p></>}
 </section>;
}
